INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a2a52de2-03d7-5666-b026-0045a5ca4aa8','TEXT','The Rainwater Notebook','Sienna liked helping at the school courtyard, especially when there was a small job that nobody had planned. One Thursday, Sienna noticed the rain gauge was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
