INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('4f573601-4e50-53e9-a199-e96ff854a996','TEXT','The Paper Kite Map','Noah liked helping at the open oval, especially when there was a small job that nobody had planned. One Wednesday, Noah noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('49ab4e02-5f7f-5fdd-9ec6-2e645e4551f0','TEXT','The Night Garden List — A Different Day','Ruby liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Friday, Ruby noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
