INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a97aa4d1-1205-59af-a9cf-672d771ce574','TEXT','The Bicycle Bell Project','Eli liked helping at the bike path, especially when there was a small job that nobody had planned. One Tuesday, Eli noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Eli decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('d2d2ca2c-3854-5543-9a96-108fd650bfa9','TEXT','The Orange Tree Calendar — A Different Day','Amara liked helping at the school orchard, especially when there was a small job that nobody had planned. One Friday, Amara noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
